#!/usr/bin/env bash
# nvidia/nvsentinel v1.20.0 - base variant: no-pod-monitor
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/nvidia-nvsentinel-v1-20-0.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install the cub CLI with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

# Installer is a cub plugin. Check it before this script does any work.
if ! cub installer --help >/dev/null 2>&1; then
  printf 'The cub installer plugin is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kustomize >/dev/null 2>&1; then
  printf 'kustomize is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the no-pod-monitor base variant into ./nvidia-nvsentinel-v1-20-0-no-pod-monitor"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/nvidia-nvsentinel:v1.20.0@sha256:d17f99a1d606e58f80cd2bf6cf9fc736d72554eab18a6e3c22cb5f2fc96586f4 --base no-pod-monitor --work-dir ./nvidia-nvsentinel-v1-20-0-no-pod-monitor --non-interactive --namespace nvsentinel

say "Read what was rendered; nothing has touched the cluster yet"
ls ./nvidia-nvsentinel-v1-20-0-no-pod-monitor/out/manifests

say "Ensure the nvsentinel namespace exists"
kubectl create namespace nvsentinel --dry-run=client -o yaml | kubectl apply -f -

if [ -d ./nvidia-nvsentinel-v1-20-0-no-pod-monitor/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./nvidia-nvsentinel-v1-20-0-no-pod-monitor/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./nvidia-nvsentinel-v1-20-0-no-pod-monitor/out/manifests

say "Done. The cluster received exactly the files in ./nvidia-nvsentinel-v1-20-0-no-pod-monitor/out."
